using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Returns the current server uptime and version info.")]
    public static string GetServerStatus(
        [Description("If true, include extended diagnostics")] bool verbose = false)
    {
        var info = $"Server: HttpMcpServer v1.0 | Uptime: {Environment.TickCount64 / 1000}s";
        if (verbose)
        {
            info += $" | OS: {Environment.OSVersion} | CLR: {Environment.Version}";
        }
        return info;
    }

    [McpServerTool, Description("Looks up a configuration value by key name.")]
    public static string LookupConfig(
        [Description("The configuration key to look up (e.g. 'MaxRetries', 'Timeout')")] string key)
    {
        var config = AppConfigResource.GetConfigDictionary();
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class AppConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "Application Settings",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppSettings()
    {
        return JsonSerializer.Serialize(GetConfigDictionary(), new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource(
        UriTemplate = "config://app/features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns the current feature flag states.")]
    public static string GetFeatureFlags()
    {
        var features = new Dictionary<string, bool>
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["NewDashboard"] = true,
            ["AuditLogging"] = true
        };

        return JsonSerializer.Serialize(features, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    internal static Dictionary<string, object> GetConfigDictionary() => new()
    {
        ["AppName"] = "HttpMcpServer",
        ["Version"] = "1.0.0",
        ["MaxRetries"] = 3,
        ["Timeout"] = 30,
        ["LogLevel"] = "Information",
        ["Environment"] = "Development"
    };
}

